import{_ as n,l as A,o as e,c as i,v as r,p as l,x as t,d as s,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"APV","description":"","frontmatter":{"title":"APV","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apv.md","filePath":"econ/apv.md","lastUpdated":1789023840000}'),V={name:"econ/apv.md"};function P(c,a,_,C,h,E){const o=A("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="apv" tabindex="-1">APV <a class="header-anchor" href="#apv" aria-label="Permalink to &quot;APV&quot;">​</a></h1><div class="epigraph"><p>把项目当成全股权来估值，再把融资副作用的现值逐项加上去；当债务水平随时间变动时，这比把税盾塞进一个常数 WACC 更不容易混口径。</p><footer>—— Myers, Interactions of Corporate Financing and Investment Decisions—Implications for Capital Budgeting, Journal of Finance 1974</footer></div><p><a href="/econ/capm-project-discount">上一课</a>给出项目的 \\(r_U\\)。WACC 要求目标 \\(D/V\\) 大致稳定，才能把税盾折进贴现率。本课缺口是 Myers（1974）的调整现值（APV）：融资与投资互动时，先按无杠杆折项目，再加税盾、补贴、发行成本、积压等副作用。不重推 CAPM，不重写权衡的 \\(D^\\ast\\) 公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>WACC 把税盾藏在分母里，暗含「每期按价值再平衡债务」。LBO、项目融资、有明确还本表的债务、或有补贴的出口信贷，债务路径是金额而不是比率。此时常数 WACC 既对不上税盾的风险，也说不清某一期多借一块债值多少。Myers 的处方：</p> \\[\\mathrm{APV}=V_U+\\mathrm{PV}(\\text{融资副作用}). \\]<p>\\(V_U\\) 用 \\(r_U\\) 折未杠杆 FCF。税盾按债务计划单独折——安全税盾可用 \\(r_D\\)，不确定税盾用更接近 \\(r_U\\) 的利率。缺口不是再发明一种 NPV，而是：投资决策与融资决策互动时，把互动写成可加的现值，而不是混进一个权重。</p><p><span class="marginnote">Myers 1974 的原问题是：用 WACC 或用股权现金流，都会在「接受项目会改变最优债务」时把投资与融资绞在一起。APV 把绞在一起的部分摊开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先算全股权价值：项目期望 FCF 用 \\(r_U\\)（上一课的 \\(\\beta_A\\)）。再列副作用清单：（1）利息税盾；（2）发行成本与折价（优序的柠檬可放这里）；（3）补贴贷款、政府担保；（4）财务困境与积压的期望损失；（5）债务纪律减少的代理成本（Jensen，符号与（4）相反）。能定量的进 APV，不能定量的至少禁止用「再调 WACC 两个点」来假装定量。</p><p>债务金额给定时，第 \\(t\\) 期税盾 \\(\\tau_c r_D D_{t-1}\\)，若违约风险低，按 \\(r_D\\) 折。债务按价值比例再平衡时，APV 与 Miles–Ezzell WACC 应对齐；对齐失败说明口径不一致。Brealey–Myers：能用 WACC 就用；债务路径复杂就改 APV。</p>',11)),(e(),l(d,null,{default:t(()=>[p(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20VU%5B%22VU%3A%20rU%20%E6%8A%98%E6%9C%AA%E6%9D%A0%E6%9D%86%20FCF%22%5D%20--%3E%20APV%5B%22APV%22%5D%0A%20%20TS%5B%22%E7%A8%8E%E7%9B%BE%E7%8E%B0%E5%80%BC%22%5D%20--%3E%20APV%0A%20%20ISS%5B%22%E5%8F%91%E8%A1%8C%E6%88%90%E6%9C%AC%20%2F%20%E6%9F%A0%E6%AA%AC%22%5D%20--%3E%20APV%0A%20%20DIST%5B%22%E5%9B%B0%E5%A2%83%E4%B8%8E%E7%A7%AF%E5%8E%8B%22%5D%20--%3E%20APV%0A%20%20SUB%5B%22%E8%A1%A5%E8%B4%B4%E8%B4%B7%E6%AC%BE%22%5D%20--%3E%20APV%0A%20%20APV%20--%3E%20DEC%5B%22%E6%8E%A5%E5%8F%97%3A%20APV%20%3E%200%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与<a href="/econ/debt-overhang">债务积压</a>：副作用可以是负的——存量债使本项目的一部分 NPV 落到原债权人。APV 把「对股东的 NPV」和「对企业的 NPV」分开：资本预算若站在股东，要扣掉输送给原债的部分。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是价值可加性再次发挥作用。无杠杆项目价值由资产风险定价；税法、发行市场、破产法各给出一块可加的转移。WACC 是「税盾这一块恰好能写成贴现率调整」时的简写；副作用不只税盾时，简写不够。Tirole 的融资合同把控制权与现金流一起切，APV 仍是部分均衡的现值加法，不是完整合同理论——后课动态资本结构会把税盾与违约放进同一扩散过程。</p><p>投资与融资的互动：接受项目提高债务容量，税盾增加，APV 高于 \\(V_U\\)；若项目提高困境概率，容量下降。用公司旧 WACC 折新项目，等于假设互动为零或与旧资产相同。</p><h3 id="不要把-apv-当成可以把任意「战略溢价」加进去的抽屉" tabindex="-1">不要把 APV 当成可以把任意「战略溢价」加进去的抽屉 <a class="header-anchor" href="#不要把-apv-当成可以把任意「战略溢价」加进去的抽屉" aria-label="Permalink to &quot;不要把 APV 当成可以把任意「战略溢价」加进去的抽屉&quot;">​</a></h3><p>协同、增长期权应进 \\(V_U\\) 的现金流或进<a href="/econ/real-options-theory">实物期权</a>，不是标一个正的「战略 APV」。副作用清单只放融资引起的转移。否则 APV 变成把 NPV 调过关的第二套 IRR。</p><p><span class="marginnote">调整现值与「调整后的折现率」对偶：同一税盾，要么加在分子，要么减在分母。两边都加是重复计算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在本课展开 Leland 的内生违约边界；那是资本结构动态单元的第一课。也不要把政府补贴写成「社会 NPV」——APV 站在股东（或企业）的税后转移，社会成本另计。个人税与 Miller 均衡把税盾缩小，副作用项要改有效税率，不是把 APV 放弃。</p><p>后课默认：债务路径不规则时用 APV；\\(V_U\\) 用 \\(r_U\\)，税盾与发行、困境分项加。WACC 是稳定 \\(D/V\\) 时的简写。下一课把分子上的自由现金流预测写清楚，否则分母再精确也是精确地错。</p><p>不要用 APV 重写限价簿上的做市商库存。那是协议与存货，不是项目融资副作用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>APV = 无杠杆价值 + 融资副作用；债务金额路径复杂时优于常数 WACC。</li><li>税盾、发行成本、补贴、积压分项加；不要与 WACC 重复计算税盾。</li><li>投资改变债务容量时，互动必须显式出现，不能靠公司旧门槛蒙混。</li><li>出处：Myers, <em>Journal of Finance</em> 1974；Brealey, Myers and Allen。</li></ul>',13))])}const B=n(V,[["render",P]]);export{u as __pageData,B as default};
